
/**
 * Client
**/

import * as runtime from './runtime/library.js';
import $Types = runtime.Types // general types
import $Public = runtime.Types.Public
import $Utils = runtime.Types.Utils
import $Extensions = runtime.Types.Extensions
import $Result = runtime.Types.Result

export type PrismaPromise<T> = $Public.PrismaPromise<T>


/**
 * Model Inquiry
 * 
 */
export type Inquiry = $Result.DefaultSelection<Prisma.$InquiryPayload>
/**
 * Model DraftProposal
 * ── Phase-2 Module 7: AI Service Finder leads ────────────────
 *    When the AI chat widget qualifies a visitor and captures their
 *    email, a draft proposal is auto-created so it appears in the
 *    admin Proposals tab ready to review and send.
 */
export type DraftProposal = $Result.DefaultSelection<Prisma.$DraftProposalPayload>
/**
 * Model WebhookLog
 * ── Phase-2 Module 7: Paystack webhook audit log ─────────────
 *    Every incoming webhook (charge.success, transfer.success, …)
 *    is persisted here — the money trail the admin can inspect.
 */
export type WebhookLog = $Result.DefaultSelection<Prisma.$WebhookLogPayload>
/**
 * Model AdminSession
 * 
 */
export type AdminSession = $Result.DefaultSelection<Prisma.$AdminSessionPayload>
/**
 * Model AdminUser
 * 
 */
export type AdminUser = $Result.DefaultSelection<Prisma.$AdminUserPayload>
/**
 * Model AdminRole
 * 
 */
export type AdminRole = $Result.DefaultSelection<Prisma.$AdminRolePayload>
/**
 * Model AdminAuditLog
 * 
 */
export type AdminAuditLog = $Result.DefaultSelection<Prisma.$AdminAuditLogPayload>
/**
 * Model Subscriber
 * 
 */
export type Subscriber = $Result.DefaultSelection<Prisma.$SubscriberPayload>
/**
 * Model Post
 * 
 */
export type Post = $Result.DefaultSelection<Prisma.$PostPayload>
/**
 * Model PostAuthor
 * ── BATCH 5 (§43): author profiles ─────────────────────
 *    Public articles show a real author entity (name / role / bio /
 *    avatar) instead of a hardcoded string. Posts keep the legacy
 *    `author` string for email-template back-compat; it is kept in
 *    sync with the selected profile's name.
 */
export type PostAuthor = $Result.DefaultSelection<Prisma.$PostAuthorPayload>
/**
 * Model Comment
 * ── BATCH 5 (§23/§92): post comments with moderation ──
 *    Moderation-first: every comment starts `pending` and only
 *    appears publicly after admin approval — anonymous commenting
 *    is never a direct spam vector. Replies nest one level
 *    (parentId → top-level comment).
 */
export type Comment = $Result.DefaultSelection<Prisma.$CommentPayload>
/**
 * Model Reaction
 * ── BATCH 5 (§24): lightweight post reactions ──────────
 *    One reaction per (visitor, type) — the unique constraint
 *    makes duplicate reactions impossible; toggle-off deletes.
 */
export type Reaction = $Result.DefaultSelection<Prisma.$ReactionPayload>
/**
 * Model MediaAsset
 * ── BATCH 5 (§20/§21/§25/§93): media assets ────────────
 *    Optimized uploads (sharp resize + webp for images),
 *    validated (magic bytes + MIME + size + sanitized name),
 *    stored under data/uploads/media/ (gitignored, outside
 *    executable dirs) and streamed via /api/media/{id}.
 */
export type MediaAsset = $Result.DefaultSelection<Prisma.$MediaAssetPayload>
/**
 * Model Testimonial
 * 
 */
export type Testimonial = $Result.DefaultSelection<Prisma.$TestimonialPayload>
/**
 * Model EmailLog
 * 
 */
export type EmailLog = $Result.DefaultSelection<Prisma.$EmailLogPayload>
/**
 * Model EmailProviderConfig
 * ── Phase 29: AES-256-GCM-encrypted email provider credentials ──
 *    The failover chain (apps_script → resend → mailtrap → maileroo)
 *    iterates enabled rows in `priority` order (lower = tried first).
 *    `credentialsEnc` is base64(iv|ciphertext|tag) — never plaintext.
 *    Rotation requires re-entering all credentials because the
 *    encryption key is what makes the ciphertext readable.
 */
export type EmailProviderConfig = $Result.DefaultSelection<Prisma.$EmailProviderConfigPayload>
/**
 * Model ReceivedEmail
 * ── Phase-1 Module 2: audit-trail models ────────────────────
 *    Directive asked for Mongoose models; this stack is Prisma +
 *    SQLite (deployed on Render with a persistent disk — migrating
 *    to Mongo would break the deployment kit and every preserved
 *    workflow). Equivalent Prisma models deliver the same audit
 *    goals without the regression. Mappings:
 *      received_emails → ReceivedEmail
 *      sent_emails     → EmailLog (extended above — the admin Email
 *                        log UI already reads it; a duplicate table
 *                        would drift)
 *      invoices        → Invoice
 *      events          → EventRecord
 *      whatsapp_messages → WhatsAppMessage
 */
export type ReceivedEmail = $Result.DefaultSelection<Prisma.$ReceivedEmailPayload>
/**
 * Model Invoice
 * 
 */
export type Invoice = $Result.DefaultSelection<Prisma.$InvoicePayload>
/**
 * Model Payment
 * ── BATCH 1: Payment record (directive §26) ───────────────────
 *    A dedicated Payment entity separate from WebhookLog — the canonical
 *    "money received" record. Created on webhook charge.success or on
 *    manual reconciliation. WebhookLog remains the raw audit trail; this
 *    Payment row is the normalized, customer+invoice-linked record the
 *    admin CRM's "Payment history" panel reads (directive §44).
 */
export type Payment = $Result.DefaultSelection<Prisma.$PaymentPayload>
/**
 * Model EventRecord
 * 
 */
export type EventRecord = $Result.DefaultSelection<Prisma.$EventRecordPayload>
/**
 * Model WhatsAppMessage
 * 
 */
export type WhatsAppMessage = $Result.DefaultSelection<Prisma.$WhatsAppMessagePayload>
/**
 * Model AnalyticsEvent
 * ── Phase-2 Module 8C: first-party analytics events ─────────
 *    GA4 receives the same names via dataLayer/gtag; this table is
 *    the source of truth the Admin Analytics dashboard queries
 *    (works with or without a GA4 property configured).
 */
export type AnalyticsEvent = $Result.DefaultSelection<Prisma.$AnalyticsEventPayload>
/**
 * Model BackupLog
 * ── Phase-2 Module 8B: daily 02:00 backup audit trail ────────
 *    Every backup run (Google Drive target when credentials exist,
 *    local rotation fallback otherwise) is recorded here.
 */
export type BackupLog = $Result.DefaultSelection<Prisma.$BackupLogPayload>
/**
 * Model Customer
 * ── Stage 11 CRM: canonical Customer record ─────────────────────
 *    The CRM unifies Inquiries + Invoices + EmailLog + WhatsAppMessage
 *    + Subscribers by customerEmail. A Customer row is the canonical
 *    contact: name, email, phone, whatsapp, company, status, tags,
 *    notes (free-text), source (manual | csv | inquiry | ai_chat |
 *    invoice), and an internal notes trail.
 * 
 *    Why a separate Customer table vs. just virtualizing off Inquiries:
 *    - Lets the admin add prospects that haven't submitted an inquiry
 *      yet (e.g. from a CSV upload, a networking event, a referral).
 *    - Gives the admin a stable ID to attach notes / tags / status to,
 *      independent of which channel the contact came in through.
 *    - Makes the CRM searchable + filterable in one query (no N-table
 *      union needed at render time).
 * 
 *    The detail view still aggregates interactions from the existing
 *    tables by customerEmail so historical rows created BEFORE the CRM
 *    feature ship are visible too — zero migration needed.
 */
export type Customer = $Result.DefaultSelection<Prisma.$CustomerPayload>
/**
 * Model CustomerNote
 * ── Stage 11 CRM: internal note trail per customer ─────────────
 */
export type CustomerNote = $Result.DefaultSelection<Prisma.$CustomerNotePayload>
/**
 * Model CustomerMessage
 * ── Stage 11 CRM: admin-to-customer message log ────────────────
 *    Records every outbound message sent FROM the admin CRM. The
 *    actual delivery is via the existing email pipeline (notify.ts →
 *    Apps Script for branded Gmail) and the WhatsApp mini-service.
 *    Replies come back via the inbound WhatsApp + email-poll routes
 *    and land in WhatsAppMessage / ReceivedEmail — the CRM detail
 *    view aggregates both sides into one timeline.
 */
export type CustomerMessage = $Result.DefaultSelection<Prisma.$CustomerMessagePayload>
/**
 * Model ImportJob
 * ── Master Platform Evolution Directive §16/§17 — AI CRM Import ──
 *    Background import job for LARGE customer imports (thousands of
 *    rows). Lifecycle:
 *      created → fetching → extracting → mapping → awaiting_approval
 *      → importing → completed | failed | cancelled
 *    The admin always gets a preview + approval gate before any DB
 *    write (§16 "Do not blindly import AI-extracted records").
 *    Import happens in CHUNKS (default 200 rows/chunk); failed chunks
 *    are tracked individually and can be RETRIED (§17).
 *    rows Json holds the canonical mapped rows (validated preview +
 *    import source). For 10k rows ≈ 3 MB jsonb — fine for Postgres.
 */
export type ImportJob = $Result.DefaultSelection<Prisma.$ImportJobPayload>
/**
 * Model AdRequest
 * ── BATCH 6 (§37–42): Advertisement marketplace ──────────────
 *    Lifecycle (§38):  new → reviewing → (awaiting_customer)? →
 *      approved (pricing sent) → payment_pending → paid →
 *      scheduled → active → completed | rejected | expired | paused
 *    Display window is authoritative on startAt/endAt (§42) — the
 *    status engine flips scheduled→active and active→completed/expired
 *    lazily on read (same pattern as Post.publishDuePosts).
 */
export type AdRequest = $Result.DefaultSelection<Prisma.$AdRequestPayload>
/**
 * Model CalendarEvent
 * ── BATCH 10 (§33–36): Appointment calendar + event registration ──
 *    CalendarEvent carries the six §33 entry kinds (appointment |
 *    meeting | webinar | event | deadline | task) — invoice due
 *    dates are DERIVED client-side from unpaid invoices (no rows),
 *    so the calendar is always in sync with payments.
 *    reminderOffsets: minutes BEFORE start; negative = after start
 *    (post-event follow-up, §34). remindersSent is a batch-level
 *    marker { "<offsetMinutes>": ISO }; EventRegistration keeps a
 *    per-registrant reminderStates map for re-registration resets.
 *    Times are stored UTC; every render/interpret uses Africa/Lagos
 *    (no DST, fixed +60) — see lagosInputValueToUtc in events.ts.
 */
export type CalendarEvent = $Result.DefaultSelection<Prisma.$CalendarEventPayload>
/**
 * Model EventRegistration
 * §34 — public event/webinar registration. One live row per
 *    (event, email): cancelling then re-registering REACTIVATES the
 *    row with a fresh reminderStates map. Consent (reminders +
 *    confirmations) is explicit and timestamped.
 */
export type EventRegistration = $Result.DefaultSelection<Prisma.$EventRegistrationPayload>
/**
 * Model AiKnowledge
 * ── Batch 11 (§50/§51) — Admin-configurable AI knowledge base ────
 *    SINGLETON row (id is always "singleton") holding the controlled
 *    business knowledge layer the chat AI reasons from (§49 step 3):
 *    profile, contact + hours, FAQ, policies, services & pricing,
 *    education. The AI may state ONLY figures present here (figure
 *    guard in ai-chat.ts) — anything unpriced gets "custom proposal".
 *    JSON columns keep default literals so an empty row still
 *    serializes cleanly (same convention as CalendarEvent).
 */
export type AiKnowledge = $Result.DefaultSelection<Prisma.$AiKnowledgePayload>
/**
 * Model ChatConversation
 * ── Batch 11 (§58) — AI conversation monitoring ──────────────────
 *    One row per widget sessionId. status: "ai" (bot answers) →
 *    "takeover_requested" (§60 escalation flagged; AI holds) →
 *    "human" (§59 accepted; AI silent, messages queue for the agent).
 *    §61 decline returns status to "ai" with contact alternatives.
 *    sentiment/urgency reflect the LATEST turn (LLM-labelled).
 */
export type ChatConversation = $Result.DefaultSelection<Prisma.$ChatConversationPayload>
/**
 * Model ChatMessage
 * §58 — full transcript. role: user (visitor) | assistant (Okomba AI)
 *    | agent (human takeover) | system (handover/decline notices).
 */
export type ChatMessage = $Result.DefaultSelection<Prisma.$ChatMessagePayload>
/**
 * Model AiAuditLog
 * ── Batch 11 (§63) — AI action audit trail ───────────────────────
 *    Every autonomous or semi-autonomous AI action gets a row:
 *    ai.handoff.requested / accepted / declined, ai.chat.escalated,
 *    ai.knowledge.updated, ai.proposal.created … Same never-throws
 *    convention as auditAdmin (admin-rbac.ts).
 */
export type AiAuditLog = $Result.DefaultSelection<Prisma.$AiAuditLogPayload>
/**
 * Model AiAutonomyConfig
 * ── Batch 12 (§52) — AI autonomy control center ──────────────────
 *    Singleton config row (id="singleton", AiKnowledge pattern):
 *    master switch, per-action approval levels (§53), daily email
 *    budget, recipient/service allowlists, escalation rules and the
 *    never-do list. SAFE defaults are seeded by src/lib/ai-autonomy.ts
 *    (enabled=false — autonomy ships dark; every action "review").
 */
export type AiAutonomyConfig = $Result.DefaultSelection<Prisma.$AiAutonomyConfigPayload>
/**
 * Model AiActionLog
 * ── Batch 12 (§54/§55) — AI action ledger ────────────────────────
 *    Every (semi-)autonomous AI action gets one row: what it wanted to
 *    do, who/what triggered it, the evaluated approval level, the
 *    lifecycle status, the generated content snapshot (draftJson) and
 *    the delivery result (resultJson). Pending rows are the admin's
 *    approval queue (approve/decline routes).
 */
export type AiActionLog = $Result.DefaultSelection<Prisma.$AiActionLogPayload>
/**
 * Model AiCampaign
 * ── Batch 12 (§56) — AI mass-email campaign ──────────────────────
 *    Admin briefs a goal; the AI drafts subject/body templates with
 *    §57 {{tokens}}; the admin previews per-recipient renders, edits,
 *    approves, then sends (batched, rate-limited, budget-gated).
 */
export type AiCampaign = $Result.DefaultSelection<Prisma.$AiCampaignPayload>
/**
 * Model AiCampaignRecipient
 * §57 — per-recipient materialization: each row is rendered ONLY
 *    from that recipient's own CRM data (privacy rule: one recipient's
 *    values never feed another's render).
 */
export type AiCampaignRecipient = $Result.DefaultSelection<Prisma.$AiCampaignRecipientPayload>
/**
 * Model Student
 * §65 — student account. passwordHash/passwordSalt follow the
 *    AdminUser scrypt split (admin-rbac.ts hashPassword/verifyPassword
 *    are reused verbatim — one crypto convention platform-wide).
 */
export type Student = $Result.DefaultSelection<Prisma.$StudentPayload>
/**
 * Model StudentSession
 * §65 — student session. Same audit-hardened convention as
 *    AdminSession: the DB stores the SHA-256 HASH of the raw token;
 *    the httpOnly cookie `okomba_student_session` carries the raw
 *    256-bit hex token (32+ hex chars). 30-day expiry.
 */
export type StudentSession = $Result.DefaultSelection<Prisma.$StudentSessionPayload>
/**
 * Model Course
 * §66 — course (catalogue root). priceNgn Int (free courses for
 *    now); published gates the public catalogue.
 */
export type Course = $Result.DefaultSelection<Prisma.$CoursePayload>
/**
 * Model Module
 * §66 — module inside a course (HTML → CSS → JavaScript …).
 */
export type Module = $Result.DefaultSelection<Prisma.$ModulePayload>
/**
 * Model Lesson
 * §66 — lesson. kind text|video; content = markdown body;
 *    isPreview flags free-preview lessons (content visible to
 *    non-enrolled visitors per the course-detail gating rule).
 */
export type Lesson = $Result.DefaultSelection<Prisma.$LessonPayload>
/**
 * Model LessonResource
 * §64 — downloadable materials. kind pdf|link|slide|exercise.
 */
export type LessonResource = $Result.DefaultSelection<Prisma.$LessonResourcePayload>
/**
 * Model Quiz
 * §64 — quiz, one per lesson (lessonId unique). passScore is a
 *    percent (default 70).
 */
export type Quiz = $Result.DefaultSelection<Prisma.$QuizPayload>
/**
 * Model QuizQuestion
 * §64 — quiz question. options is a Json ARRAY of {id, text}
 *    (Prisma primitive lists are not allowed → Json).
 */
export type QuizQuestion = $Result.DefaultSelection<Prisma.$QuizQuestionPayload>
/**
 * Model QuizAttempt
 * §64 — quiz attempt, server-graded. All attempts kept
 *    (multiple retakes allowed). answers Json [{questionId, optionId}].
 */
export type QuizAttempt = $Result.DefaultSelection<Prisma.$QuizAttemptPayload>
/**
 * Model Enrollment
 * §64 — enrollment. unique(studentId, courseId) → idempotent
 *    re-enroll returns the existing row. status flips to completed
 *    automatically when every lesson is completed.
 */
export type Enrollment = $Result.DefaultSelection<Prisma.$EnrollmentPayload>
/**
 * Model LessonProgress
 * §64 — progress tracking per lesson per student.
 *    unique(studentId, lessonId) → upsert. secondsSpent accumulates
 *    watch-time pings.
 */
export type LessonProgress = $Result.DefaultSelection<Prisma.$LessonProgressPayload>
/**
 * Model Announcement
 * §64 — admin-posted announcements. audience all|course;
 *    students see audience=all + their enrolled courses.
 */
export type Announcement = $Result.DefaultSelection<Prisma.$AnnouncementPayload>

